using System;using System.IO;using System.Reflection;using UnityEngine;
public static class AuraSweepAcceptance {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 public static object Main(){var a=typeof(EchoSphere.Runtime.EchoSphereRuntime).Assembly;var st=a.GetType("EchoSphere.Presentation.NativeWorldSurface");var nt=a.GetType("EchoSphere.Presentation.NativeWorldSphereFamilies");object Call(object o,string name,params object[] ar)=>o.GetType().GetMethod(name,F).Invoke(o,ar);var go=new GameObject("Aura sweep acceptance");var s=go.AddComponent(st);Call(s,"Initialize");Call(s,"SetViewport",360f,240f,1.75f);var n=Activator.CreateInstance(nt,true);Color32[] Read(){var rt=(RenderTexture)st.GetProperty("CompositeTexture",F).GetValue(s);var old=RenderTexture.active;RenderTexture.active=rt;var im=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);im.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);im.Apply();RenderTexture.active=old;var px=im.GetPixels32();UnityEngine.Object.DestroyImmediate(im);return px;}double worst=0;try{for(int sample=0;sample<6;sample++){Color32[] before=null;for(int mode=0;mode<2;mode++){nt.GetField("UseVectorAuraForValidation",F).SetValue(n,mode==0);Call(s,"Begin",Vector2.zero);Call(s,"ResetTransform");Call(n,"BeginFrame");Call(n,"DrawOrbit",s,28d,Color.cyan,sample*.31d,.7d,"aura",sample*.19d,null,false);Call(s,"End");var px=Read();if(mode==0)before=px;else{long sum=0;for(int i=0;i<px.Length;i++)sum+=Math.Abs(px[i].r-before[i].r)+Math.Abs(px[i].g-before[i].g)+Math.Abs(px[i].b-before[i].b);double mean=sum/(double)(px.Length*3);worst=Math.Max(worst,mean);if(mean>.3)throw new Exception("aura difference "+mean);}}}var cpu=new double[2];for(int mode=0;mode<2;mode++){nt.GetField("UseVectorAuraForValidation",F).SetValue(n,mode==0);var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<200;i++){Call(s,"Begin",Vector2.zero);Call(n,"BeginFrame");Call(n,"DrawOrbit",s,28d,Color.cyan,i*.016d,.7d,"aura",.5+.5*Math.Sin(i*.03d),null,false);}watch.Stop();cpu[mode]=watch.Elapsed.TotalMilliseconds/200;}return new{result="PASS",samples=6,worstMeanRgb=worst,editorAuraOrbitCpuBeforeMs=cpu[0],editorAuraOrbitCpuAfterMs=cpu[1]};}finally{((IDisposable)n).Dispose();UnityEngine.Object.DestroyImmediate(go);}}
}
